import json
from pathlib import Path

WP = "B-REQ-PRD-S1"
ROOT = Path(__file__).resolve().parents[4]
GAPS = ROOT / "_work" / "msr" / "gaps" / f"{WP}.jsonl"
ASM = ROOT / "_work" / "msr" / "assumptions" / f"{WP}.jsonl"

FSD = "Recovery Workbench FSD S1 Valuation and route v3 (03 Requirements and specifications/Recovery Workbench Functional Specifications by Module v6)"
ARCH = "Recovery Workbench Architecture v5 Text Extract v1"
TD = "Recovery Workbench Temporal and Drools Design Text Extract v1"
MAP = "Recovery Workbench Microservice Ownership Map v1"
BRD = "Recovery Workbench Business Requirements Epics 3 to 8 v1"
PROG = "Recovery Workbench Business Requirements Program v4"


def g(n, title, source, section, description, evidence, typ, area, sev, wave, legacy, role, proposed):
    return {
        "id": f"CG-{WP}-{n}",
        "title": title,
        "source": source,
        "section": section,
        "description": description,
        "evidence": evidence,
        "type": typ,
        "area": area,
        "severity": sev,
        "needed_by_wave": wave,
        "legacy_ref": legacy,
        "owner_role": role,
        "asm": f"ASM-{WP}-{n}",
        "proposed": proposed,
        "wp": WP,
    }


def a(n, text, why, read, applied, conf, confirm, impact, gap="auto"):
    # Rows 1 to 19 are paired with the gap of the same number; 20 and up carry no gap.
    resolved = f"CG-{WP}-{n}" if gap == "auto" and n <= 19 else ("auto" if gap == "auto" else gap)
    return {
        "id": f"ASM-{WP}-{n}",
        "text": text,
        "why": why,
        "read": read,
        "gap": "" if resolved in ("", "auto") else resolved,
        "applied_in": applied,
        "confidence": conf,
        "confirm": confirm,
        "impact": impact,
        "wp": WP,
    }


